"""Pinned local notification redaction. No credentials or profile reads.

The host verifies its full build manifest before source_for. MAX resources
change per build, so executable identity additionally pins every relevant
instruction, Qt slot and ABI constructor; notifications.dll is immutable.
"""
from __future__ import annotations
import copy, hashlib, json, struct
import re
from pathlib import Path
import pefile
from build_mod import payload_file

