def specification_from_bytes(images: dict[str,bytes], *, module_paths: dict[str,Path]) -> dict:
    if set(images) != {"max.exe","notifications.dll"} or set(module_paths) != set(images):
        raise ValueError("Missing notification native images")
    result=copy.deepcopy(FIXED)
    for item in result["modules"]:
        name=item["name"];data=images[name]
        if type(data) is not bytes:
            raise ValueError("Unsupported notification native image")
        sha=hashlib.sha256(data).hexdigest()
        if name=="notifications.dll" and (sha!=item["baselineSha256"] or len(data)!=item["baselineSize"]):
            raise ValueError("Unsupported notification backend")
        try:
            pe=pefile.PE(data=data,fast_load=True)
            if pe.FILE_HEADER.Machine!=0x8664 or pe.OPTIONAL_HEADER.Magic!=0x20b:
                raise ValueError("Unsupported notification PE layout")
            for pin in item["pins"]:
                expected=bytes.fromhex(pin["expected"])
                section=pe.get_section_by_rva(pin["rva"])
                if section is None or not section.Characteristics&0x20000000 or pe.get_data(pin["rva"],len(expected))!=expected:
                    raise ValueError("Unsupported notification native instructions")
            base=pe.OPTIONAL_HEADER.ImageBase
            for slot in item["slots"]:
                if struct.unpack("<Q",pe.get_data(slot["vtableRva"]+slot["slot"],8))[0]!=base+slot["thunkRva"]:
                    raise ValueError("Unsupported notification native slots")
            item.update(modulePath=str(module_paths[name]),moduleSha256=sha,moduleSize=len(data),imageSize=pe.OPTIONAL_HEADER.SizeOfImage)
            pe.close()
        except (pefile.PEFormatError,struct.error,IndexError,KeyError) as exc:
            raise ValueError("Unsupported notification PE image") from exc
    return result

def specification(root: Path) -> dict:
    paths={name:payload_file(root,name) for name in ("max.exe","notifications.dll")}
    return specification_from_bytes({name:path.read_bytes() for name,path in paths.items()},module_paths=paths)

def source_for(root: Path, policy: dict, *, generic_image_path: Path | str | None = None) -> str:
    if generic_image_path is None:
        raise ValueError("Missing generic notification image")
    image=Path(generic_image_path).resolve(strict=True)
    if not image.is_file() or image.stat().st_size>4096:
        raise ValueError("Invalid generic notification image")
    config={"specification":specification(root),"policy":policy,"genericImagePath":str(image)}
    source=Path(__file__).with_name("notification_monitor.js").read_text(encoding="utf8")
    return "const VALMAX_NOTIFICATION="+json.dumps(config,separators=(",",":"))+";\nconst VALMAX_NOTIFICATION_PINS="+json.dumps(FIXED,separators=(",",":"))+";\n"+source

def updater_source_for(bridge: dict) -> str:
    """Create the host-connected channel for one already bootstrapped guardian.

    The host eternalizes the guardian before loading this ordinary updater.
    Only the updater receives post() calls and sends per-request ACK messages.
    """
    if (type(bridge) is not dict or set(bridge)!={"kind","schema","pointer","size","magic"}
            or bridge.get("kind")!="valmax-notification-bridge-ready" or type(bridge.get("schema")) is not int
            or bridge["schema"]!=1 or type(bridge.get("size")) is not int or bridge["size"]!=65536
            or bridge.get("magic")!="56414c4e42523031" or type(bridge.get("pointer")) is not str
            or re.fullmatch(r"0x[1-9a-f][0-9a-f]{0,15}",bridge["pointer"]) is None):
        raise ValueError("Invalid notification guardian bridge")
    source=Path(__file__).with_name("notification_updater.js").read_text(encoding="utf8")
    return "const VALMAX_NOTIFICATION_BRIDGE="+json.dumps(bridge,separators=(",",":"))+";\n"+source
